// === HIER PFLEGEN ===
const CONFIG = {
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',

  // Goodie-Position, die rabattiert wird
  zielSku: 'ZB-2026-08-02',

  // Rabattsatz in Prozent auf diese Position (1–100)
  rabattProzent: 20,

  // Titel des Rabatts in der Bestellung.
  // {code} = Rabattcode aus der CSV, {pct} = rabattProzent
  rabattBeschreibungTemplate: 'Rabattcode {code} ({pct} % Goodie-Rabatt)',

  // true = Position überspringen, wenn dort schon ein Rabatt gebucht ist (kein Doppelrabatt)
  ueberspringenWennSchonRabattiert: true,

  notifyCustomer: false,
  staffNote: 'Automatischer Goodie-Rabatt auf ZB-2026-08-02.',

  // Bestellungen ausschließen: 'BB-12345' oder numerische orderId. [] = keine.
  ausnahmen: []
};

const pct = Number(CONFIG.rabattProzent);
if (!(pct > 0 && pct <= 100)) {
  throw new Error('Config.rabattProzent muss zwischen 0 und 100 liegen, ist: ' + CONFIG.rabattProzent);
}

const staticData = $getWorkflowStaticData('global');
staticData.config = CONFIG;
staticData.toFix = [];
staticData.skipped = [];
staticData.done = [];

// CSV-Binary unverändert durchreichen
return $input.all();

// Akzeptiert die Mapping-CSV (Bestellnummer;Email;Rabattcode),
// einen Shopify-Orders-Export ODER eine einfache Liste von Bestellnummern.
const rows = $input.all().map(i => i.json);

const NAME_KEYS  = ['name', 'bestellnummer', 'bestellung', 'ordername', 'order name', 'order_name'];
const ID_KEYS    = ['id', 'orderid', 'order id', 'order_id'];
const CODE_KEYS  = ['rabattcode', 'rabatt-code', 'code', 'discount code', 'discount_code',
                    'gutschein', 'gutschein_codes', 'gutscheincode'];
const EMAIL_KEYS = ['email', 'e-mail', 'customer: email', 'customer_email', 'kunde email'];

// Header normalisieren: BOM weg, trimmen, lowercase
const normRow = (row) => {
  const o = {};
  for (const [k, v] of Object.entries(row || {})) {
    o[String(k).replace(/^\uFEFF/, '').trim().toLowerCase()] = v;
  }
  return o;
};

const pick = (row, keys) => {
  for (const k of keys) {
    const v = row?.[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

let lastId = null;
const seen = new Set();
const out = [];

for (const raw of rows) {
  const row = normRow(raw);
  let name  = pick(row, NAME_KEYS).replace(/^#/, '');
  let id    = pick(row, ID_KEYS);
  const code  = pick(row, CODE_KEYS);
  const email = pick(row, EMAIL_KEYS);

  // Fallback: CSV mit nur einer Spalte ohne bekannten Header
  if (!name && !id) {
    const first = Object.values(row).map(v => String(v ?? '').trim()).filter(Boolean)[0] || '';
    if (/^\d{6,}$/.test(first)) id = first;
    else if (first) name = first.replace(/^#/, '');
  }

  if (id) lastId = id;
  else if (name && lastId && rows.length > 1) id = lastId;

  if (!id && !name) continue;

  const key = id || name.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  out.push({
    orderId: id ? Number(id) : null,
    orderName: name || null,
    rabattCode: code || null,
    email: email || null
  });
}

if (!out.length) {
  throw new Error('Keine Bestellnummern in der CSV erkannt. Erwartet wird eine Spalte "Bestellnummer"/"Name" oder "Id".');
}

const ohneCode = out.filter(o => !o.rabattCode).length;
if (ohneCode === out.length) {
  throw new Error('In der CSV wurde keine Spalte "Rabattcode" gefunden – ohne Code kann der Rabatt nicht zugeordnet werden.');
}

return out.map(o => ({ json: o }));

// toFix leeren, Token durchreichen, alle Bestellungen weitergeben.
const staticData = $getWorkflowStaticData('global');
staticData.toFix = [];
staticData.skipped = [];
staticData.done = [];

const token = $json.access_token;
const orders = $('Bestellungen extrahieren (dedupe)').all().map(i => i.json);

return orders.map(o => ({ json: { ...o, accessToken: token } }));

const item = $input.item.json;
const config = $getWorkflowStaticData('global').config;
const base = `https://${config.shop}.myshopify.com/admin/api/${config.apiVersion}`;
const fields = 'id,name,created_at,tags,total_discounts,line_items';

// Mit orderId direkt, sonst über die Bestellnummer suchen.
const url = item.orderId
  ? `${base}/orders/${item.orderId}.json?fields=${fields}`
  : `${base}/orders.json?status=any&limit=2&name=${encodeURIComponent(item.orderName)}&fields=${fields}`;

return { json: { ...item, url } };

const response = $input.first().json;
const body = response.body || response;
const order = body.order || (Array.isArray(body.orders) ? body.orders[0] : null);

const staticData = $getWorkflowStaticData('global');
const config = staticData.config;
if (!Array.isArray(staticData.toFix)) staticData.toFix = [];
if (!Array.isArray(staticData.skipped)) staticData.skipped = [];

const angefragt = $('URL bauen (Bestellung)').first().json;
const ZIEL = String(config.zielSku).trim().toLowerCase();
const num = (v) => Number(v || 0);
const norm = (v) => String(v ?? '').trim().replace(/^#/, '').toLowerCase();
const AUSNAHMEN = (Array.isArray(config.ausnahmen) ? config.ausnahmen : []).map(norm);

const skip = (grund, extra = {}) => {
  staticData.skipped.push({
    orderName: order?.name || angefragt.orderName || null,
    orderId: order?.id || angefragt.orderId || null,
    rabattCode: angefragt.rabattCode || null,
    grund, ...extra
  });
};

if (!order) {
  skip('Bestellung über die API nicht gefunden');
} else if (!angefragt.rabattCode) {
  skip('Kein Rabattcode in der CSV-Zeile');
} else if (AUSNAHMEN.length && (AUSNAHMEN.includes(norm(order.name)) || AUSNAHMEN.includes(norm(order.id)))) {
  skip('Bestellung steht in Config.ausnahmen');
} else {
  const lineItems = order.line_items || [];
  const aktiv = lineItems.filter(li =>
    String(li.sku || '').trim().toLowerCase() === ZIEL && num(li.current_quantity) > 0);

  if (!aktiv.length) {
    skip(`Position ${config.zielSku} nicht aktiv in der Bestellung`);
  } else {
    const rabattSumme = (li) => (li.discount_allocations || [])
      .reduce((s, a) => s + num(a.amount), 0);

    const offen = config.ueberspringenWennSchonRabattiert
      ? aktiv.filter(li => rabattSumme(li) <= 0)
      : aktiv;

    if (!offen.length) {
      skip('Position ist bereits rabattiert', {
        vorhandenerRabatt: aktiv.map(li => rabattSumme(li).toFixed(2)).join(', ')
      });
    } else {
      staticData.toFix.push({
        orderId: order.id,
        orderName: order.name,
        createdAt: order.created_at,
        rabattCode: angefragt.rabattCode,
        email: angefragt.email || null,
        positionen: offen.map(li => ({
          lineItemId: li.id,
          title: li.title,
          variantId: li.variant_id,
          sku: li.sku,
          preis: li.price,
          quantity: li.quantity,
          currentQuantity: li.current_quantity,
          vorhandenerRabatt: rabattSumme(li).toFixed(2)
        }))
      });
    }
  }
}

return [{
  json: {
    collectedCount: staticData.toFix.length,
    skippedCount: staticData.skipped.length
  }
}];

// Kontrolle vor dem Schreiben: was wird rabattiert, was wurde übersprungen.
const staticData = $getWorkflowStaticData('global');
const config = staticData.config;
const collected = staticData.toFix || [];
const skipped = staticData.skipped || [];

const titel = (code) => String(config.rabattBeschreibungTemplate)
  .replace('{code}', code || '')
  .replace('{pct}', String(config.rabattProzent));

const rows = [{
  json: {
    ZUSAMMENFASSUNG: true,
    zielSku: config.zielSku,
    rabattProzent: config.rabattProzent,
    rabattBeschreibungTemplate: config.rabattBeschreibungTemplate,
    anzahlBestellungen: collected.length,
    anzahlPositionen: collected.reduce((s, o) => s + o.positionen.length, 0),
    anzahlUebersprungen: skipped.length
  }
}];

for (const order of collected) {
  for (const pos of order.positionen) {
    const brutto = Number(pos.preis) * Number(pos.currentQuantity || pos.quantity || 1);
    const rabatt = brutto * Number(config.rabattProzent) / 100;
    rows.push({
      json: {
        orderName: order.orderName,
        orderId: order.orderId,
        email: order.email,
        rabattCode: order.rabattCode,
        rabattTitel: titel(order.rabattCode),
        createdAt: order.createdAt,
        sku: pos.sku,
        title: pos.title,
        einzelpreis: pos.preis,
        menge: pos.currentQuantity,
        erwarteterRabatt: rabatt.toFixed(2),
        lineItemId: pos.lineItemId,
        orderGid: `gid://shopify/Order/${order.orderId}`,
        lineItemGid: `gid://shopify/CalculatedLineItem/${pos.lineItemId}`
      }
    });
  }
}

for (const s of skipped) {
  rows.push({ json: { UEBERSPRUNGEN: true, ...s } });
}

return rows;

// Bereitet je zu rabattierende Position EIN Item vor
const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

const out = [];
for (const order of collected) {
  for (const pos of order.positionen) {
    out.push({
      json: {
        orderId: order.orderId,
        orderName: order.orderName,
        orderGid: `gid://shopify/Order/${order.orderId}`,
        rabattCode: order.rabattCode,
        email: order.email || null,
        lineItemId: pos.lineItemId,
        // Fallback, falls die CalculatedOrder keine lineItems liefert
        lineItemGidFallback: `gid://shopify/CalculatedLineItem/${pos.lineItemId}`,
        sku: pos.sku,
        preis: pos.preis,
        quantity: pos.currentQuantity || pos.quantity
      }
    });
  }
}

if (!out.length) {
  return [{ json: { WARNUNG: 'Keine Position zum Rabattieren gefunden', anzahl: 0 } }];
}

return out;

// TESTGATE: verarbeitet nur die erste gefundene Position.
// Für den Vollauf diesen Node deaktivieren oder löschen.
return $input.all().slice(0, 1);

const staticData = $getWorkflowStaticData('global');
const config = staticData.config;
const done = staticData.done || [];
const skipped = staticData.skipped || [];

const rows = [{
  json: {
    ZUSAMMENFASSUNG: true,
    zielSku: config.zielSku,
    rabattProzent: config.rabattProzent,
    erfolgreichRabattiert: done.length,
    uebersprungen: skipped.length
  }
}];

for (const d of done) rows.push({ json: { ERFOLG: true, ...d } });
for (const s of skipped) rows.push({ json: { UEBERSPRUNGEN: true, ...s } });

return rows;

const item = $('Loop Over Items').item.json;

const body = {
  query: `mutation orderEditBegin($id: ID!) {
    orderEditBegin(id: $id) {
      calculatedOrder {
        id
        lineItems(first: 100) {
          edges { node { id sku quantity title } }
        }
      }
      userErrors { field message }
    }
  }`,
  variables: { id: item.orderGid }
};

return [{
  json: {
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
}];

const resp = $input.first().json;
const begin = resp?.data?.orderEditBegin;
const errs = begin?.userErrors || [];
if (errs.length) throw new Error('orderEditBegin userErrors: ' + JSON.stringify(errs));

const calcOrderId = begin?.calculatedOrder?.id;
if (!calcOrderId) throw new Error('Keine calculatedOrder.id erhalten: ' + JSON.stringify(resp));

const loopItem = $('Loop Over Items').item.json;
const config = $getWorkflowStaticData('global').config;
const ZIEL = String(config.zielSku).trim().toLowerCase();

const nodes = (begin?.calculatedOrder?.lineItems?.edges || []).map(e => e.node);

// 1. Treffer über die aus der REST-lineItemId gebaute GID
let ziel = nodes.find(n => String(n.id) === loopItem.lineItemGidFallback);
// 2. sonst über die SKU
if (!ziel) ziel = nodes.find(n => String(n.sku || '').trim().toLowerCase() === ZIEL);
// 3. sonst Fallback auf die konstruierte GID (falls lineItems leer zurückkommt)
const lineItemGid = ziel ? ziel.id : loopItem.lineItemGidFallback;

if (!ziel && !nodes.length) {
  console.log('Warnung: calculatedOrder.lineItems leer, nutze konstruierte GID');
} else if (!ziel) {
  throw new Error(`Position ${config.zielSku} nicht in der CalculatedOrder gefunden. Vorhanden: `
    + nodes.map(n => n.sku).join(', '));
}

return [{
  json: {
    calcOrderId,
    lineItemGid,
    sku: ziel?.sku || loopItem.sku,
    quantity: ziel?.quantity ?? loopItem.quantity,
    orderName: loopItem.orderName,
    orderGid: loopItem.orderGid,
    rabattCode: loopItem.rabattCode,
    email: loopItem.email || null,
    preis: loopItem.preis
  }
}];

const item = $input.item.json;
const config = $getWorkflowStaticData('global').config;

if (!item.rabattCode) {
  throw new Error(`Kein Rabattcode für Bestellung ${item.orderName} – Abbruch vor dem Schreiben.`);
}

// Rabattcode MUSS im Titel stehen, damit er in der Bestellung zuordenbar ist
const beschreibung = String(config.rabattBeschreibungTemplate)
  .replace('{code}', item.rabattCode)
  .replace('{pct}', String(config.rabattProzent));

const body = {
  query: `mutation orderEditAddLineItemDiscount($id: ID!, $lineItemId: ID!, $discount: OrderEditAppliedDiscountInput!) {
    orderEditAddLineItemDiscount(id: $id, lineItemId: $lineItemId, discount: $discount) {
      calculatedLineItem {
        id
        sku
        quantity
        discountedUnitPriceSet { shopMoney { amount currencyCode } }
      }
      addedDiscountStagedChange { id description }
      userErrors { field message }
    }
  }`,
  variables: {
    id: item.calcOrderId,
    lineItemId: item.lineItemGid,
    discount: {
      percentValue: Number(config.rabattProzent),
      description: beschreibung
    }
  }
};

return {
  json: {
    ...item,
    rabattBeschreibung: beschreibung,
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.first().json;
const add = resp?.data?.orderEditAddLineItemDiscount;
const errs = add?.userErrors || [];
if (errs.length) throw new Error('orderEditAddLineItemDiscount userErrors: ' + JSON.stringify(errs));

const prev = $('Query bauen (Rabatt)').item.json;

return [{
  json: {
    ...prev,
    gqlBody: undefined,
    accessToken: undefined,
    rabattierterEinzelpreis: add?.calculatedLineItem?.discountedUnitPriceSet?.shopMoney?.amount ?? null,
    waehrung: add?.calculatedLineItem?.discountedUnitPriceSet?.shopMoney?.currencyCode ?? null,
    rabattTitel: add?.addedDiscountStagedChange?.description ?? prev.rabattBeschreibung ?? null
  }
}];

const item = $input.item.json;
const config = $getWorkflowStaticData('global').config;

const body = {
  query: `mutation orderEditCommit($id: ID!, $notifyCustomer: Boolean, $staffNote: String) {
    orderEditCommit(id: $id, notifyCustomer: $notifyCustomer, staffNote: $staffNote) {
      order { id name }
      userErrors { field message }
    }
  }`,
  variables: {
    id: item.calcOrderId,
    notifyCustomer: config.notifyCustomer === true,
    staffNote: `${config.staffNote} ${config.rabattProzent} % auf ${config.zielSku}, Code: ${item.rabattCode}`
  }
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.first().json;
const commit = resp?.data?.orderEditCommit;
const errs = commit?.userErrors || [];
if (errs.length) throw new Error('orderEditCommit userErrors: ' + JSON.stringify(errs));

const prev = $('Rabatt-Ergebnis prüfen').item.json;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.done)) staticData.done = [];
staticData.done.push({
  orderName: prev.orderName,
  email: prev.email || null,
  rabattCode: prev.rabattCode,
  sku: prev.sku,
  menge: prev.quantity,
  preisVorher: prev.preis,
  rabattierterEinzelpreis: prev.rabattierterEinzelpreis,
  rabattTitel: prev.rabattTitel
});

return [{
  json: {
    status: 'OK',
    orderName: prev.orderName,
    rabattCode: prev.rabattCode,
    sku: prev.sku,
    rabattierterEinzelpreis: prev.rabattierterEinzelpreis,
    waehrung: prev.waehrung,
    committedOrder: commit?.order || null
  }
}];
